Definition icells (m : mem) : Prop :=
  ro_cells asegs m 0xfdb10 [C8 (Z_to_bv 64 0x10cc78)]            (* [comment removed for export] *)
  /\ ro_cells asegs m 0xfe678 [C8 (Z_to_bv 64 0x10d959)]         (* [comment removed for export] *)
  /\ ro_cells asegs m 0xff9d8 [C8 (Z_to_bv 64 0xf3e48)]         (* [comment removed for export] *)
